92	    /// keeps at most one `boolean` keyword variant when several aliased
93	    /// references resolve to the same keyword.
94	    pub fn normalized_boolean_union_variants(mut types: Vec<Self>) -> Vec<Self> {
95	        let has_boolean = types.iter().any(|ty| matches!(&**ty, TypeData::Boolean));
96	        let has_true = types.iter().any(|ty| ty.is_boolean_literal(true));
97	        let has_false = types.iter().any(|ty| ty.is_boolean_literal(false));
98	
99	        if !(has_boolean || has_true && has_false) {
100	            return types;
101	        }
102	
103	        let template = (!has_boolean)
104	            .then(|| {
105	                types
106	                    .iter()
107	                    .find(|ty| ty.is_boolean_literal(true) || ty.is_boolean_literal(false))
108	                    .cloned()
109	            })
110	            .flatten();
111	
112	        let mut seen_boolean = false;
113	        types.retain(|ty| {
114	            if matches!(&**ty, TypeData::Boolean) {
115	                if seen_boolean {
