fn is_union_wider_than_returns(variants: &[Type], returns: &[Type]) -> bool {
    let all_covered = returns.iter().all(|ret| {
        variants
            .iter()
            .any(|ann_v| types_match(ann_v, ret) || is_nonunion_wider(ann_v, ret))
