/// Whether a union variant absorbs all other variants, making any narrowing of
/// the annotation meaningless (`any`, `unknown`, and `never`).
fn union_variant_absorbs_all(ty: &Type) -> bool {
    matches!(
        &**ty,
        TypeData::AnyKeyword
            | TypeData::UnknownKeyword
            | TypeData::NeverKeyword
